/**  dry-run 预览条目：只描述将要发生的改动，不执行任何写操作 */
export type SoftwareUpdatePreview = SoftwareUpdatePreview_Serialize | SoftwareUpdatePreview_Deserialize;

/**  dry-run 预览条目：只描述将要发生的改动，不执行任何写操作 */
export type SoftwareUpdatePreview_Deserialize = {
	/**  包名 */
	pkgname: string,
	/**  PKGBUILD 绝对路径（不可预览时为空串） */
	pkgbuild_path: string,
	/**  原 pkgver */
	old_pkgver: string,
	/**  目标 pkgver */
	new_pkgver: string,
	/**  原 pkgrel */
	old_pkgrel: string,
	/**  目标 pkgrel（固定重置为 1） */
	new_pkgrel: string,
	/**  仅列出发生变化行的文本 diff */
	diff: string,
	/**  不可预览的原因；为 None 时该条目可安全执行 */
	error?: string | null,
};

/**  dry-run 预览条目：只描述将要发生的改动，不执行任何写操作 */
export type SoftwareUpdatePreview_Serialize = {
	/**  包名 */
	pkgname: string,
	/**  PKGBUILD 绝对路径（不可预览时为空串） */
	pkgbuild_path: string,
	/**  原 pkgver */
	old_pkgver: string,
	/**  目标 pkgver */
	new_pkgver: string,
	/**  原 pkgrel */
	old_pkgrel: string,
	/**  目标 pkgrel（固定重置为 1） */
	new_pkgrel: string,
	/**  仅列出发生变化行的文本 diff */
	diff: string,
	/**  不可预览的原因；为 None 时该条目可安全执行 */
	error: string | null,
};

/**
 *  写回状态（列表仅含 is_outdated = 1 的包，本枚举不持久化到数据库）
 * 
 *  说明：这里只描述「本地 PKGBUILD 是否已处理」，不描述「是否需要更新」——
 *  后者由 software_info.is_outdated 在版本检查阶段决定，页面不再重复判断。
 */
export type SoftwareUpdateStatus = 
/**  本地 PKGBUILD 仍是旧版本，等待写回 */
"pending" | 
/**  本地 PKGBUILD 已写到上游版本，等待推送 AUR */
"local_updated" | 
/**  本地包目录缺少 PKGBUILD，无法写回 */
"missing" | 
/**  无上游版本信息，无法写回 */
"no_upstream";

/**  「从 AUR 同步」全量对齐的结果统计 */
export type SyncFromAurResult = {
	/**  成功写入（新建 + 更新）的包数量 */
	synced: number,
	/**  本地新建的包数量 */
	created: number,
	/**  失败的包数量（写入失败或 AUR 未返回） */
	failed: number,
};

/**  上游 URL 验证状态枚举 */
export type UpstreamUrlStatus = 
/**  URL 可达，返回 200 */
"ok" | 
/**  URL 返回 404 */
"not_found" | 
/**  URL 返回 403 或 401 */
"forbidden" | 
/**  URL 返回重定向 (3xx) */
"redirected" | 
/**  URL 返回服务器错误 (5xx) */
"server_error" | 
/**  连接超时 */
"timeout" | 
/**  连接错误（DNS 解析失败、连接被拒绝等） */
"connection_error" | 
/**  其他错误 */
"other_error";

