/**  验证结果结构 */
export type ValidateResult_Serialize = {
	software_id: number,
	pkgname: string,
	upstream_url: string | null,
	status: UpstreamUrlStatus,
};

export type Value = null | boolean | number | string | Value[] | { [key in string]: Value };
